## Example: Switching to a Secrets Manager

Below is a minimal example showing how you might pull a JWT secret from **AWS Secrets Manager** and use it within your Express app.

1. **Add dependency**

```bash
npm install @aws-sdk/client-secrets-manager
```

2. **Create a helper (`secrets.js`)**

```js
// secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

async function getSecret(secretName) {
  const data = await client.send(new GetSecretValueCommand({ SecretId: secretName }));
  if ('SecretString' in data) {
    return JSON.parse(data.SecretString);
  }
  // Handle binary secrets if needed
  return Buffer.from(data.SecretBinary, 'binary').toString('utf-8');
}

module.exports = { getSecret };
```

3. **Load at startup**

```js
// app.js
require('dotenv').config();          // Load local env variables (e.g., AWS credentials)
const { getSecret } = require('./secrets');

(async () => {
  const secrets = await getSecret('my-jwt-secret');   // { jwt: '...up-to-256-char...' }

  const jwtSecret = secrets.jwt;
  // Pass jwtSecret to your auth middleware or store in a process-wide variable
})();
```

4. **Use the secret in the middleware**

```js
// auth.js
const jwt = require('jsonwebtoken');

module.exports = function auth(req, res, next) {
  const header = req.headers.authorization;
  if (!header) return res.sendStatus(401);

  const token = header.split(' ')[1];
  try {
    req.user = jwt.verify(token, global.jwtSecret);   // or pass as argument
    return next();
  } catch {
    return res.sendStatus(401);
  }
};
```

5. **Deployment**  

* In your CI/CD pipeline, store the secret `my-jwt-secret` in Secrets Manager.  
* Pass `AWS_REGION` and `AWS_PROFILE`/`AWS_ACCESS_KEY_ID` + `AWS_SECRET_ACCESS_KEY` as environment variables for the runtime.

> **Tip** – For local development, you can keep a `.env` file with mock credentials **[(ignored in `.gitignore`)]** to bootstrap the helper.

