### 3.2 Enable CORS with a whitelist

Modern browsers enforce the Same‑Origin Policy. If you plan to expose this API to browsers, you’ll need CORS – but **only** for trusted domains.

```js
const cors = require('cors');

const corsOptions = {
  origin: ['https://trusteddomain.com', 'http://localhost:3000'], // adjust
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));
```

### 3.3 Rate limiting

Prevents DoS and brute‑force style abuse.

```js
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests
  handler: (req, res) => {
    res.status(429).json({ error: 'Too many requests. Try again later.' });
  },
});

app.use(limiter);
```

Place this middleware **before** defining routes to protect every endpoint.

### 3.4 Logging (Morgan + winston)

```js
const morgan = require('morgan');
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [new winston.transports.Console()],
});

app.use(morgan('combined', { stream: { write: (message) => logger.info(message.trim()) } }));
```

