  windowMs: 60 * 1000,          // 1 minute
  max: 200,                     // limit each IP to 200 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

/** ------------------------------------------------------------------
 *  3️⃣ Routes – keep public logic separate from protected logic
 *  ----------------------------------------------------------------- */
