  // In a real app you would pull this data from a DB and filter
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/** ------------------------------------------------------------------
 *  4️⃣ Optional: Error handling middleware (catch-all)
 *  ----------------------------------------------------------------- */
