  console.error(err);            // Crash‑level logging is fine, expand with winston
  res.status(err.status || 500).json({
    message: err.message || 'Internal Server Error',
  });
});

/** ------------------------------------------------------------------
 *  5️⃣ Start server
 *  ----------------------------------------------------------------- */
