## 3.  Future improvements (authentication, data validation, etc.)

Below is a minimal JWT‑based auth setup to illustrate the concepts. In production you’d store the secret in an HSM, rotate tokens, use refresh tokens, etc.

```js
// Add to package.json: "jsonwebtoken": "^9.0.0" (or latest)
// Add file: auth.js

// auth.js
const jwt = require('jsonwebtoken');
const secret = process.env.JWT_SECRET || 'devsecret';

module.exports = {
  generateToken: (payload, options = {}) => {
    return jwt.sign(payload, secret, { expiresIn: '1h', ...options });
  },

  authenticate: (req, res, next) => {
    const authHeader = req.headers['authorization'];
    if (!authHeader) return res.status(401).json({ message: 'Missing auth header' });

    const token = authHeader.split(' ')[1]; // Bearer <token>
    if (!token) return res.status(401).json({ message: 'Malformed auth header' });

    jwt.verify(token, secret, (err, decoded) => {
      if (err) return res.status(403).json({ message: 'Invalid token' });
      req.user = decoded;   // Attach user data for later middleware/routes
      next();
    });
  },
};
```

