// app.js – Hardened App Skeleton
// -----------------------------------------------------------

require('dotenv').config();          // load .env
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { body, param, validationResult } = require('express-validator');

const app = express();

/* ---------------- Core Middlewares ---------------- */
app.use(helmet());                                // secure HTTP headers
app.use(cors({ origin: 'https://trustedorigin.com' })); // whitelist
app.use(express.json());                          // JSON body parser
app.use(morgan('combined'));                       // request logging

/* ---------------- Security: Rate Limiting -------------- */
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,      // 15 min
  max: 200,                     // limit each IP
  message: { error: 'Too many requests, try again later.' }
});
app.use(limiter);

/* ---------------- Authentication ----------------------- */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Token required' });

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

/* ---------------- Routes ------------------------------ */
// health – publicly visible, but still sanitized
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users – protected endpoints
app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example POST – validated & sanitized
app.post(
  '/users',
  authenticateToken,
  body('name').isString().trim().escape(),
  body('email').isEmail().normalizeEmail(),
  async (req, res, next) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }
      // Persist user to database here – use parameterized queries
      // e.g., db.query('INSERT INTO users(name, email) VALUES($1, $2)', [req.body.name, req.body.email])
      res.status(201).json({ message: 'User created' });
    } catch (err) {
      next(err);                     // forward to global error handler
    }
  }
);

/* ---------------- Global Error Handler ----------------- */
app.use((err, req, res, next) => {   // eslint-disable-line no-unused-vars
  console.error(err);                // log internally
  const msg = process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message;
  res.status(err.status || 500).json({ error: msg });
});

/* ---------------- Server Startup ----------------------- */
const PORT = process.env.PORT || 3000;
app.listen(PORT, () =>
  console.log(`Server running on port ${PORT} (${process.env.NODE_ENV})`)
);

module.exports = app;
```

