### 6. Authentication Skeleton (JWT example)

```bash
npm install jsonwebtoken
```

```js
const jwt = require('jsonwebtoken');

app.use((req, res, next) => {
  if (req.path === '/health') return next(); // exempt

  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ message: 'Missing auth token' });

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload; // attach payload to request
    next();
  } catch (e) {
    console.error(e);
    res.status(401).json({ message: 'Invalid token' });
  }
});
```

Now your `/users` route could be protected like:

